-- 2403 🏋️ Exercises from the book "beat-the-press-with-single-double-pivots-build-up-play-and-sessions-from-flick-k" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'beat-the-press-with-single-double-pivots-build-up-play-and-sessions-from-flick-k');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Turn or pass back pivot decision drill', 'passing_opposed', 'passive', 'in_possession', 47, 47, 'Training Session 1: Practice 1', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'Teach the defensive midfielder to read whether he is being pressed and choose between turning forward or playing back to exploit space.', 'Area split into two halves, each with a group of blues (GK, CB, DM, AM, F) and mannequins standing in for the first and third pressing lines; one live red player acts as the second line in each half. Groups sit at opposite ends.', 'GK and CB exchange a one-two, then GK finds the DM, who checks the red. If the red steps up to press, the DM returns the ball to the CB (or via GK) and it goes quickly into the AM; if the red holds, the DM turns and plays the AM directly or through the forward as a link. AM combines with F around a mannequin, F runs between mannequins onto a through ball and passes to the GK of the other group to restart.', 'Red player chooses each time whether to press the DM or hold his position.', NULL, 'Scan before receiving; read the presser early; play quickly into the space the press leaves.', '2 groups of blues (GK, CB, DM, AM, F) + 2 red pressers, with rotation GK > CB > DM > AM > F > other group''s GK', 12, NULL, NULL, NULL, NULL, NULL, false, true, true, NULL, 10),
  ('6 plus GK v 2 break the lines', 'phase_of_play', 'overload', 'in_possession', 48, 49, 'Training Session 1: Practice 2', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'Break the second pressing line by reacting to whether the nearest central midfielder presses the pivot or holds.', 'Half pitch from our goal, three mini goals across the far end. Blues: GK, two centre backs, a single pivot (6), two attacking midfielders (8, 10) and a forward (9). Reds: two live central midfielders; mannequins form the rest of their 4-4-2 shape.', 'GK moves the ball with the centre backs, then plays the pivot behind the first line. Variation 1: if the red midfielder holds, the pivot takes the ball on the half-turn and plays forward, teammates making a triangle or diamond (e.g. 9 sets back for 8 to dribble on and score). Variation 2: the red presses the pivot as the GK passes, so he plays back to GK or a centre back and the ball is switched quickly to the free side to find 8 between the lines, who plays in 9 to score.', 'Blues score in the mini goals; reds try to win the ball.', 'Variation 1 = red holds, receive and turn; Variation 2 = red presses, pass back and switch to exploit space behind him.', 'Spot the press early and decide fast; move the ball quickly into the space behind the press; use sharp combinations to break the lines.', '6 (+GK) v 2 plus mannequins', 9, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 20),
  ('Draw press, break lines 8v6 positional game', 'phase_of_play', 'overload', 'in_possession', 50, 51, 'Session 1: Practice 3', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'Building out from the GK against a 4-2 press with a single pivot, drawing pressure to free a player behind the second line.', 'Half pitch plus, big goal with blue GK, mannequins as the red third line; yellow zone between lines is the blue starting zone for 3 attackers (8, 10, 9); reds in a 4-2 shape; small goals for reds to counter into.', 'GK circulates with the centre backs then finds the DM (6) behind the first line; the 6 turns or plays back depending on whether the nearest red midfielder presses, then the ball goes through the second line and the team breaks the third line (mannequins) to score.', 'Reds may only enter the yellow zone once a blue player receives there. Reds win the ball and counter to score within 8-12 seconds.', 'Variation 2: GK dribbles forward, red forwards squeeze inside, GK plays a centre back wide who reads the red midfielders and plays straight to the AM (10) or via link players, then into the forward''s diagonal run.', 'Spot pressure early and choose turn/back/switch quickly; circulate fast to exploit the space behind the pressing line.', '8v6 (+GKs)', 16, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 30),
  ('Break lines 3-zone 11v11 game (4-3-3)', 'conditioned_game', 'opposed', 'in_possession', 52, 52, 'Session 1: Practice 4', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'Deciding whether to turn, recycle or dribble forward to find the free attacking midfielder behind the second pressing line in a 4-3-3 build-up.', '11v11 on three quarters of a pitch, goals and GKs both ends; a yellow middle zone marks space between the lines as a guide only.', 'Blues build from the GK and look to find the 8 or 10 behind the second line, then progress past the third line and score. Reds press high after the GK''s first pass.', 'No zone restrictions. Reds who win the ball counter to score within 12 seconds.', NULL, 'Read the reds'' defensive actions; be aware when the GK dribbles forward and creates room for the centre backs.', '11v11', 22, 22, '3/4 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 40),
  ('Turn-or-pass decision double pivot circuit', 'passing_opposed', 'passive', 'in_possession', 62, 62, 'Session 2: Practice 1', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'Double pivot midfielders deciding to turn or pass back depending on whether a defender presses them.', 'Pitch split into two halves, each with GK, CB, LDM, RDM, AM and F; mannequins mark the first and third pressing lines with one red player in the second line.', 'GK plays a one-two with one pivot then passes to the other pivot, who checks the red player. If pressed he plays to the CB or other pivot and the ball goes quickly to the AM behind the red; if not pressed he turns and plays the AM directly or via the forward as link. AM and F combine around the mannequin and the F receives a through ball and plays to the other group.', 'Rotation: GK to CB to LDM to RDM to AM to F to GK of the other group.', NULL, 'Scan before receiving; read the red player''s reaction.', '2 groups of 6 + 2 defenders', 14, NULL, NULL, NULL, NULL, NULL, false, true, true, NULL, 50),
  ('Break lines on reactions 6v2 functional', 'phase_of_play', 'overload', 'in_possession', 63, 64, 'Session 2: Practice 2', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'Moving the ball from the GK to the attacking midfielder by reading how two pressing midfielders react (4-2-3-1).', 'Two thirds of a pitch, big goal with blue GK, three small goals at the far end; blues have GK, 2 CBs, 3 midfielders and a forward; reds have 2 central midfielders with mannequins forming the rest of a defensive shape.', 'GK circulates with the centre backs then passes to a defensive midfielder who scans first; if the nearest red holds, the 6 receives on the half-turn and plays forward, teammates forming triangles or diamonds, the forward sets for the 10 to dribble on and score.', NULL, 'Variation 2: the red midfielder presses the 6 as the GK passes, so the 6 plays back to GK or a centre back and the team switches quickly to find the free 10 via the right CB or other pivot as link; 10 then plays the forward in.', 'Recognise pressing early; move the ball quickly into space behind the second line; sharp combinations.', '6 (+GK) v 2', 9, 9, NULL, NULL, NULL, NULL, true, true, true, NULL, 60),
  ('Draw press, break lines 10v6 positional game', 'phase_of_play', 'overload', 'in_possession', 65, 66, 'Session 2: Practice 3', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'Building from the GK with a double pivot against a 4-2 press and getting through the second and third lines.', 'Big goal with blue GK; yellow zone between lines is the starting zone for blue 10, 11, 9 and 7; reds in a 4-2 shape with mannequins as the third line; far goal for the finish.', 'GK circulates with the centre backs then passes to a pivot behind the first line, who turns or passes depending on whether the nearest red midfielder steps out; blues then break the second line and pass the mannequins to score.', 'Reds can only enter the yellow zone once a blue receives inside it. Reds win the ball and counter to score within 8-12 seconds.', 'Variation 2: GK dribbles forward so the red forwards close the middle, GK passes wide to the CB (4), full back advances; the CB reads whether the red winger tucks in and plays to the winger as link to reach the 10, who plays in behind to finish.', 'Recognise pressure; communicate with key words; move the ball quickly wide or behind the second line; sharp combinations.', '10v6 (+GKs)', 18, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 70),
  ('Break lines 3-zone 11v11 game (4-2-3-1)', 'conditioned_game', 'opposed', 'in_possession', 67, 67, 'Session 2: Practice 4', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'Finding the free player behind the second line (AM or strong-side winger) by turning, recycling or dribbling in a double pivot build-up.', '11v11 on three quarters of a pitch with goals and GKs; a yellow middle zone shows the space between the lines as a guide only.', 'Blues build from the GK, find the 10 or 11 behind the second line and progress past the third line to score; reds press high after the GK''s first pass.', 'No zone restrictions. Reds who win it counter to score within 12 seconds.', NULL, 'Watch for the GK dribbling forward to draw the press and free a centre back; read the defenders and pick the right solution.', '11v11', 22, 22, '3/4 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 80),
  ('GK long pass over lines, play in behind', 'passing_opposed', 'passive', 'in_possession', 75, 76, 'Session 3: Practice 1', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'Goalkeepers hitting accurate long passes to attacking midfielders, who then decide to receive or play first time in behind depending on a defender stepping up.', 'Two GKs in the back half, centre backs at the sides, one DM (or two pivots) in the middle; two target squares for attacking midfielders; red back four on a line with two forwards; goal at the far end with poles marking the corners.', 'A centre back passes to a GK, who goes via the DM back to the other GK, who plays a long diagonal (25-35m) to an attacking midfielder in a target area. If the nearest red defender holds, the AM receives and plays in behind; if he presses, the AM plays first time or heads into space for the winger running in to score.', 'Four set repetitions alternating sides and which red defender reacts; blue outfield players rotate after each repetition.', 'Variation 2: double pivot (4-2-3-1) with LDM and RDM and only one AM, who receives in either target area.', 'GK pass accuracy into the target areas; wingers/forwards finish into the pole-marked corners; scan and react quickly.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 90),
  ('GK over second line to target zones 7v4', 'phase_of_play', 'overload', 'in_possession', 77, 78, 'Session 3: Practice 2', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'GK finding an attacking midfielder arriving in a target zone, who turns or plays first time in behind depending on pressure.', 'Two thirds of a pitch; blue GK, two centre backs plus coach, and two 5x5m target zones behind the second line; mannequins form the red lines, red back four plus 2 small goals for the counter; full goal at the far end.', 'Coach and 3 players circulate until the GK plays forward into a target zone for the 8 or 10. If free he turns and the 5v4 attack aims to score within 8 seconds; if a red defender steps up he plays first time or heads into space behind.', 'Score within 8 seconds. Reds win the ball and counter to score in the 2 small goals within 8 seconds.', 'Variation 2: 4-2-3-1 shape with only one AM in the centre who can move to any zone; attack becomes 4v4 (6v4 +GKs).', 'Accurate GK passes into the zones; quick decisions on receiving; scan and communicate; fast finishing.', '7v4 (+GKs)', 13, 13, 'Target zones 5 x 5 m', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('GK over second line 10v8 target zones', 'phase_of_play', 'overload', 'in_possession', 79, 80, 'Session 3: Practice 3', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'Building from the back against 4 defenders and 4 pressing midfielders and choosing short build or a GK aerial ball to an attacking midfielder in a target zone.', 'Two thirds of a pitch with three target zones between the lines; blue GK, back four and attackers; reds have 4 defenders and 4 midfielders, two mannequins as the first pressing line; goal at the far end.', 'Back players circulate until the GK steps forward; he either passes short behind the first line (receiver turns, passes on or recycles) or plays an aerial ball over the second line into a target zone, where the receiver turns or plays first time behind for a runner.', 'Reds win the ball and score by dribbling over the red line, receiving beyond it, or scoring in the goal.', 'Variation 2: 4-2-3-1 shape with a single AM/target player free to move into any of the three zones.', 'Accurate GK passes into target zones; quick decisions; scan and communicate before receiving; fast finishing.', '10v8 (+GKs)', 20, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 110),
  ('GK over second line 11v11 tactical game', 'conditioned_game', 'opposed', 'in_possession', 81, 81, 'Session 3: Practice 4', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'GK choosing to play behind the first line, over it or through the second line against an aggressive press, with the AM deciding to turn or play first time.', '11v11 game on a full pitch with goals and GKs, blues in a 4-3-3 build-up shape (adaptable to 4-2-3-1).', 'Play starts with the blue GK; reds press hard after the first pass and blues build out, using GK long passes to the attacking midfielders when on.', 'A goal after a long pass to an attacking midfielder counts double. Reds win it and counter to score within 10-12 seconds.', NULL, 'As earlier practices in the session.', '11v11', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Find the free player continuous possession', 'positional_game', 'overload', 'in_possession', 89, 90, 'Session 4: Practice 1', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'Creating and using a numerical advantage to find the free player and move the ball to the far end.', '18 x 12 m area with a 2v2 inside and an extra blue outside at each end; small goals at the corners for reds; coach with balls at the side.', 'Coach passes to an end player, who enters to make a 3v2; the nearest red steps up to press, blues find the free player directly or via the link at the far end, the free player passes to the opposite end and rotates outside.', 'Reds win the ball and score in either of the 2 small goals at the end where they won it.', '2/2: continuous version with opposite-end rotations - the far end player enters going the other way while the previous starter stays inside.', 'Assess quickly; diamond shape for passing lanes; move the ball efficiently to the free player; high tempo.', '3v2 rotating (2v2 + 2 end players)', 6, 6, '18 x 12 m', 18.0, 12.0, NULL, true, false, true, NULL, 130),
  ('4v3 overload 3-team zone game', 'small_sided_game', 'overload', 'in_possession', 91, 91, 'Session 4: Practice 2', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'Exploiting a numerical advantage by finding the free player, dribbling through and finishing.', 'Three teams (2 attacking, 1 defending): Zone 1 25 x 42 m in two halves, Zone 2 25 x 10 m, Zone 3 25 x 7 m with a goal and GK; 2 small goals behind Zone 1 for defenders.', 'Starts 1v1 in each half of Zone 1 and 1v1 in Zone 2; a yellow dribbles in to create 2v1 then 3v2. Attackers find the free player in Zone 1, he dribbles into Zone 2 (2v1) and they pass into Zone 3 to score.', 'After the first pass all players move freely but defenders cannot enter Zone 3. After each attack the finisher leaves and the others move one position forward; teams switch defending after a set time. Defenders win it and score in either small goal.', NULL, NULL, '3 teams', NULL, NULL, '25 x 59 m (zones 42 + 10 + 7 m)', 59.0, 25.0, NULL, true, true, true, NULL, 140),
  ('Strong side 4v3 split-pitch game (single pivot)', 'phase_of_play', 'overload', 'in_possession', 92, 92, 'Session 4: Practice 3', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'The defensive midfielder shifting to create a 4v3 around the ball and the team finding the free player to score (4-3-3).', 'Three quarters of a pitch split into two halves by a 5 m vertical channel; each half has a blue GK and goal, 6 blues (4-3-3 half) v 5 reds in a 2-2-1 shape (combined 4-4-2).', 'When the GK plays the first pass the DM (6) on each side enters to create a 4v3 around the ball; blues find the free player and go to score.', 'Reds can only press after the GK''s first pass. Reds win the ball and counter to score within 10-12 seconds. All reset after each phase.', NULL, 'Read the situation quickly and choose the best option.', '6v5 (+GKs) on each side', 24, 24, '3/4 of a full pitch split in 2', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Strong side 4v3 split-pitch game (double pivot)', 'phase_of_play', 'overload', 'in_possession', 93, 93, 'Session 4: Practice 4', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'The attacking midfielder shifting to create a 4v3 around the ball in a 4-2-3-1 build-up and finding the free player.', 'Same split-pitch set-up as the single pivot version but blues play 4-2-3-1 halves with an attacking midfielder (10) on each side instead of a DM.', 'Just before the GK''s first pass the 10 on each side enters to create a 4v3 around the ball; blues build up 6v5 (+GKs), find the free player and score.', 'Same rules and restrictions as the single pivot version.', NULL, 'Read the situation and the defensive movements; support positions for progressive lanes; create a dilemma for the opposing midfielder; fast combinations.', '6v5 (+GKs) on each side', 24, 24, '3/4 of a full pitch split in 2', NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Strong side numerical advantage 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 94, 94, 'Session 4: Practice 5', 'Flick (Barcelona), Klopp (Liverpool), Emery (Aston Villa)', 'Building from the GK and exploiting an overload on the strong side before finishing.', '11v11 on three quarters of a full pitch with goals and GKs; adaptable to 4-3-3 or 4-2-3-1.', 'Play always restarts with the blue GK; blues build up and try to create and use a 4v3 on the strong side before scoring; reds win it and counter.', 'Normal goal = 1; goal after exploiting a strong-side numerical advantage = 2. Teams switch roles after a set time.', NULL, 'Assess and position to keep passing lanes; smart decisions to use the overload; fast combinations; high tempo.', '11v11', 22, 22, '3/4 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Build-up combinations and switch to target zones', 'passing_unopposed', 'unopposed', 'in_possession', 103, 104, 'Session 5: Practice 1', 'Flick, Klopp, Emery build-up patterns', 'Rehearse quick build-up combinations through midfield followed by a long switch of play to the far side.', '40x60m area split lengthways into two halves, each with an 8x5m target zone at the end; players at stations A-E with mannequins as markers. Pattern runs on both halves at once.', 'A dribbles out of the target zone and passes to B, who combines with C, then finds D; D gets a lay-off from E and switches long into the opposite target zone for the next waiting player.', 'Players rotate A to B to C to D to E and across to the other side.', 'Variation 2: forward combination with two switch options - C moves forward and chooses to play E (who lays off to D) or D directly, then D switches.', 'Quick purposeful combinations to break lines; precise short and long passing; high tempo and sharp movement.', '10+ players in 2 groups', 10, NULL, '40 x 60 metres', 60.0, 40.0, NULL, false, false, true, NULL, 180),
  ('4v4 plus support, switch in 3-team game', 'positional_game', 'overload', 'in_possession', 105, 106, 'Session 5: Practice 2', 'Flick, Klopp, Emery build-up patterns', 'Build up with equal numbers using outside support players, then switch play to a teammate in another area, with quick transition after.', 'Two 25x15m areas, each with 2 small goals at each end; 3 teams of 4. Blues v reds 4v4 in one area with yellow outside support players around; coach with balls at the side.', 'Blues try to score in the 2 small goals or pass to a wide yellow support player; the yellow who receives switches to a yellow teammate in the other area and the outside players sprint across. After a goal or completed switch, the reds transition to defend in the second area (2 blues go outside, 2 stay) and the coach serves a new ball so yellows attack.', 'All yellows must touch the ball before scoring. Defenders who win the ball counter to the other 2 small goals. Attack must finish within a set time or the coach whistles and roles swap.', 'Adjust area size to level and age.', 'Intelligent off-ball movement; supporting players reposition to open lanes; fast combinations; quality long passes with immediate support.', '12 players in 3 teams of 4', 12, 12, '2 areas of 25 x 15 metres', 25.0, 15.0, NULL, true, false, true, NULL, 190),
  ('Split-pitch 6v6 build-up with equal numbers', 'phase_of_play', 'opposed', 'in_possession', 107, 107, 'Session 5: Practice 3', 'Flick, Klopp, Emery build-up patterns', 'Beat a high press with equal numbers on the strong side using synchronised movements, short combinations or a long ball plus support (4-3-3).', 'Pitch split into two halves with two 6v6 (+GKs) games running at once. Blues have a DM (6) and forward (9) in each; reds have 2 forwards (6 and 8).', 'Blues build up from the GK, using dynamic movements of 2-3 players to create or exploit numerical equality, then play short or long into the forward and support the second ball to get in behind and score.', 'Reds press the first receiver after the first pass and try to win the ball and score within 10-12 seconds.', NULL, 'Coordinated off-ball movement; choose short combinations or a long ball with support for the second ball.', '2 x 6v6 (+GKs)', 14, 28, 'Full pitch split into 2 halves', NULL, NULL, NULL, true, true, true, NULL, 200),
  ('11v11 three-zone game: overload or switch', 'conditioned_game', 'opposed', 'in_possession', 108, 109, 'Session 5: Practice 4', 'Flick, Klopp, Emery build-up patterns', 'Read whether the build-up side has an advantage or equal numbers and decide to combine through it or switch to the weak side.', 'Three quarters of a pitch with a 7m wide central split zone dividing left and right wide zones; full teams, GK starts.', 'GK passes into one wide zone. With a numerical advantage there (e.g. 4v3 via the free DM, 6v5 overall) blues combine quickly and score; when reds shift across to make equal numbers, blues choose to keep combining, go long with support for the second ball, or switch to the weak side.', 'Reds may only press after the GK''s first pass; if they win it they counter to score within 10-12 seconds.', 'Variation 2: reds shift early to create equality and blues must find the best option. Progression: remove the zones for natural play.', 'Read and react quickly; verbal cues; offer passing options; accurate switches; high tempo.', '11v11', 22, 22, 'Three quarters of a pitch, 3 zones', NULL, NULL, NULL, true, true, true, NULL, 210),
  ('3v2 midfield game, single pivot, end zone', 'phase_of_play', 'opposed', 'in_possession', 119, 120, 'Session 6: Practice 1', 'Flick, Klopp, Emery build-up patterns', 'Exploit a 3v2 midfield advantage against a hybrid zonal/man-marking press by finding the midfielder with the most space (single pivot 4-3-3).', 'Half pitch; blues build up from the GK in a 2-3-1 shape (one DM, two AMs, forward) against reds in a 2-2 shape; end zone with 2 small goals at the far end.', 'DM and AM stretch apart so the red central midfielder must cover two; the GK reads it and plays the through pass to the DM, who turns and, with the forward as link player, gets the ball to the free AM in the end zone to score in a small goal.', 'Reds press to win the ball and counter to score within 8-10 seconds. Red midfielders may not enter the end zone.', 'Variation 2: the red forwards shift in to block the pass to the DM, so the GK plays the centre back, who uses the AM as link to reach the DM; then the forward links to a free AM in the end zone.', 'Apply principles to overload the midfielder covering two; timing of supporting runs; read pressing cues to spot the free player.', '7+GK v 6 approx', 13, NULL, 'Half pitch with end zone', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('3v2 midfield game, double pivot, end zone', 'phase_of_play', 'opposed', 'in_possession', 121, 122, 'Session 6: Practice 2', 'Flick, Klopp, Emery build-up patterns', 'Same 3v2 midfield exploitation but from a 4-2-3-1 double pivot shape.', 'Half pitch; blues build up in a 2-2-1-1 shape (two DMs, AM, forward) against reds in a 2-2; end zone with 2 small goals.', 'GK reads the situation; if the through pass to the AM is on, the AM receives and turns and a DM acts as link player to reach the free midfielder in the end zone, who scores in a small goal.', 'Reds win the ball and counter within 8-10 seconds. Red midfielders may not enter the end zone.', 'Variation 2: the pass into the AM is too risky, so the GK plays the centre back, who finds a DM; the forward then links to the free midfielder in the end zone.', 'Overload the red midfielder covering two; timing and synchronisation of runs; read pressing cues.', '7+GK v 6 approx', 13, NULL, 'Half pitch with end zone', NULL, NULL, NULL, true, true, true, NULL, 230),
  ('11v11 exploit 3v2 midfield advantage', 'conditioned_game', 'opposed', 'in_possession', 123, 123, 'Session 6: Practice 3', 'Flick, Klopp, Emery build-up patterns', 'Apply the 3v2 midfield principles in a full game against a high press with zonal and man marking.', 'Full pitch 11v11; blues build up in 4-3-3 or 4-2-3-1, reds press high after the first pass with a hybrid zonal/man-marking midfield.', 'DM and AM stretch away from each other so the red midfielder has to control two; the ball goes to the free AM, who finishes the attack quickly with support.', 'Reds press only after the first pass.', NULL, 'Create distance from the midfielder marking two; coordinated movements to open lanes; spot pressing triggers early; quick decisions.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 240),
  ('GK pressed: build up through or over', 'passing_opposed', 'passive', 'in_possession', 139, 139, 'Session 7: Practice 1', 'Flick, Klopp, Emery build-up patterns', 'Rehearse two build-up patterns when the GK is pressed: through a link DM to the free CB, or a long ball over to the forward.', 'Two sides run at once, each with a goal at the top; GK, CB, DM (with a red marker), AM and forward (F); coach acts as presser; mannequins at sides.', 'CB passes to the GK, who is pressed by the coach. Left side: GK uses the DM as link to play the free CB, who quickly finds the AM before the red can block the lane; AM scores. Right side: GK plays long to the forward, who sets for the AM moving inside to score.', 'Can have 2 players per position, swapping each repetition.', NULL, 'Synchronised well-timed runs; support at the right moment; quick combinations.', 'About 12-14 players', 12, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 250),
  ('Link-player build-up vs aggressive press', 'passing_opposed', 'opposed', 'in_possession', 140, 140, 'Session 7: Practice 2', 'Flick, Klopp, Emery build-up patterns', 'Use link-player principles to decide whether to play the full back or the centre back when a red wide player presses.', 'As Practice 1 but blue full backs replace the forwards and a red wide player is added on each side.', 'Left side: red wide player is high, so the DM link plays the free full back, who finds the AM to turn and score. Right side: red wide player is deeper, so the DM plays back to the free CB, who plays the AM directly or via the full back as link depending on the red''s position.', NULL, NULL, 'Link player reads positioning to choose the correct receiver; quick decision to play the free player.', 'About 14-16 players', 14, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 260),
  ('8v8 three-zone find-the-free-player game', 'conditioned_game', 'opposed', 'in_possession', 141, 143, 'Session 7: Practice 3', 'Flick, Klopp, Emery build-up patterns', 'Beat ultra-aggressive pressing by moving the ball to the free player through a link player and progressing through thirds.', '50x30m, 3 zones; blues 2 CBs, 2 FBs, 3 CMs, 1 forward (4-3-1) v reds 2 CBs, midfield 4, 2 forwards; low zone starts 2(+GK)v2, middle 5v4, high 1v2.', 'Blues build up from the GK through thirds and score, finding the free player directly or via the DM as link; once the free AM receives it becomes 3v2 or 3v3 in the high zone. Restart from the blue GK.', 'Reds press ultra-aggressively and counter to score within 8-12 seconds. Midfielders start in the middle zone but can then move freely; red CBs can only enter the middle zone once a blue receives there.', 'Variation 2: DM spots the red winger stepping up to intercept and plays the full back directly. Variation 3: the forward (9) is the link player instead of the DM. Can be set up for a double pivot (4-2-3-1).', 'Link player principles; synchronised movement; accurate quick passing; read the situation; high speed of play.', '8v8 (+GKs)', 18, 18, '50 x 30 metres', 50.0, 30.0, NULL, true, true, true, NULL, 270),
  ('Half-pitch find free player vs press', 'phase_of_play', 'overload', 'in_possession', 144, 145, 'Session 7: Practice 4', 'Flick, Klopp, Emery build-up patterns', 'Find the free player against ultra-aggressive pressing, using the DM or the forward as link player.', 'Half pitch; 7 blues + GK + 1 outside forward v 6 reds; 2 small goals at the far end for blues, main goal for reds to counter on.', 'Blues play out from the GK and score in a small goal, reaching the free player directly or via the DM as link (9v6 including GK and outside forward). Reds press and try to win it and counter.', 'A red must press the GK immediately; blue forward limited to 1 touch; reds counter within 8-10 seconds; ball out of play = coach restarts to the reds.', 'Variation 2: the forward (9) is the link player instead of the DM, with the option of an aerial pass straight to him; GK or midfielders must spot when he can receive. Can be adapted to a double pivot (4-2-3-1).', 'Apply link player principles to avoid mistakes; recognise when the forward can link.', '7+1 (+GK) v 6', 15, 15, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Find free player vs ultra-aggressive press 11v11', 'conditioned_game', 'opposed', 'in_possession', 146, 146, 'Session 7: Practice 5', NULL, 'Build up past an ultra-aggressive man-marking press by finding the free player directly or through a link player.', 'Full 11v11 game; blues build up from their goalkeeper while reds press all the way up to the keeper with man marking.', 'Every restart begins with the blue keeper. Blues build up and try to score; reds press, win the ball and counter. Swap team roles after a set time.', 'Normal goal = 1; a goal scored after finding the free player with a direct pass or via a link player counts 2.', 'Can be played with a double pivot (4-2-3-1) or a single pivot (4-3-3).', 'Synchronised off-ball movement to keep shape and passing lanes; choose link player or direct option under pressure; apply link player principles.', '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Wide decision making to break lines', 'passing_opposed', 'opposed', 'in_possession', 159, 159, 'Session 8: Practice 1', 'Flick / Klopp / Emery build up patterns', 'Full back reads whether the wide defender holds or jumps and picks the right way to play past him.', '60x40m split into two halves worked at once; each half has an 8x6m box near the touchline holding a red defender, a mannequin, blues A, B, C on cones and D near the end line, a GK and a small goal.', 'GK plays to A who sets back; GK then drives a long ball to B between defender and mannequin. If the defender stays, B finds D directly or via link player C and D scores in the small goal; if the defender jumps, B heads or passes first time into space for D''s run.', 'Rotate A to B to C to D after each go; change defenders after a set number of reps or use coaches.', NULL, 'Read the defender''s reaction early; first-time header or pass when pressed quickly.', 'per half: GK + 4 blues + 1 defender', 12, NULL, '60 x 40 metres', 60.0, 40.0, NULL, true, true, true, NULL, 300),
  ('Wide line-breaking small sided game', 'phase_of_play', 'overload', 'in_possession', 160, 160, 'Session 8: Practice 2', 'Flick / Klopp / Emery build up patterns', 'Build up wide depending on the opposing winger''s press and progress to the final zone to score.', 'Same 60x40m area run on both halves, with a 30m middle zone; GK and centre back in the low zone, 4v4 in the middle zone, small goal at the far end and a big goal behind the GK.', 'GK starts and No.5 shifts wide; the nearest red moves to cover No.5 and No.3, and the GK decides to play into the low or middle zone. Blues get the ball to No.3 directly or via link player No.10, then go into the high zone and score in the small goal.', 'Only one red may leave the middle zone at a time; no reds in the final zone; GK has 5 seconds to decide. Reds who win the ball must score within 10 seconds.', 'Switch the small/large goals round so the right flank is trained too.', NULL, '5 (+GK) v 4 per half', 20, NULL, '60 x 40 metres', 60.0, 40.0, NULL, true, true, true, NULL, 310),
  ('Split-pitch read the situation build up 4-3-3', 'phase_of_play', 'overload', 'in_possession', 161, 161, 'Session 8: Practice 3', 'Flick / Klopp / Emery build up patterns', 'GK and blues pick the build up route with most space when the wingers mark two players and midfield is man-marked.', 'Pitch split lengthways into two halves, each running a 6v5 (+GKs) game at once; blues have a defensive midfielder and a forward on each side, red wingers cover full back and centre back.', 'GK starts and picks the option with most space; depending on whether the red full back stays or steps up, blues receive in space or play first time into space behind, then progress and score in the small goals.', 'GK has 5 seconds to decide after receiving a new ball. Reds press the first receiver, win it and counter to score within 10-12 seconds.', NULL, 'Decision making after the first pass is key to progressing.', '6v5 (+GKs) x2', 26, NULL, 'split pitch', NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Split-pitch read the situation build up 4-2-3-1', 'phase_of_play', 'overload', 'in_possession', 162, 162, 'Session 8: Practice 4', 'Flick / Klopp / Emery build up patterns', 'Same reading-the-press build up game played from a double pivot shape.', 'As Practice 3, two simultaneous 6v5 (+GKs) halves, but blues have an attacking midfielder and forward on both sides to fit 4-2-3-1.', 'Based on the red winger''s press, blues get the ball to the free full back either with a direct pass or through link player No.10, then attack the small goals.', 'Same rules as Practice 3: GK 5 seconds to decide; reds press first receiver and counter within 10-12 seconds.', '11v11 on three quarters of a pitch with reds using a high or ultra-aggressive press and midfield man marking.', NULL, '6v5 (+GKs) x2', 26, NULL, 'split pitch', NULL, NULL, NULL, true, true, true, NULL, 330),
  ('Find free player support zones circuit', 'passing_opposed', 'opposed', 'in_possession', 176, 176, 'Session 9: Practice 1', 'Flick / Klopp / Emery build up patterns', 'Beat man marking by dribbling to draw the marker and moving to become or use the free player.', 'Run on both sides at once; one low zone 8x5m and two larger 8x8m zones, each zone with a red presser; blues A-F on positions.', 'A plays to B who sets diagonally to C; C dribbles from zone 1 into zone 2 to trigger the red, D moves into a lane to be free and E mirrors on the other side. C passes to D directly or via E as link; D dribbles into zone 3, E offers again, and the ball goes to E directly or via F, who returns it to the start.', 'Blues complete the circuit = 1 point; reds win the ball or force an error = 1 point. All blues rotate after each go.', NULL, NULL, 'blues A-F plus reds per side', NULL, NULL, 'zones 8 x 5 m and 8 x 8 m', NULL, NULL, NULL, false, false, true, NULL, 340),
  ('Long pass and support runs combinations', 'combination', 'unopposed', 'in_possession', 177, 177, 'Session 9: Practice 2', 'Flick / Klopp / Emery build up patterns', 'Rehearse a long pass to a receiver with well-timed movements that open and exploit space against man marking.', 'Two halves worked at once, each with a small goal at both ends; A1 long passer, B receiver, C creates space, D exploits space, A2 at the far end.', 'C drops (left side as if dragging a marker; right side D overlaps) to clear space; A1 plays long to B who sets the ball into D''s path; D dribbles forward, passes into the small goal and moves to A2. Repeat in the opposite direction.', 'Rotations A1 to B to C to D to A2.', NULL, 'Intelligent, well-timed movement to disrupt man marking.', '5+ per half', 10, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 350),
  ('Single pivot build up half pitch 7v7', 'phase_of_play', 'opposed', 'in_possession', 178, 179, 'Session 9: Practice 3', 'Flick / Klopp / Emery build up patterns', 'Find the free player to progress against full pitch man marking from a 4-3-3 low-half shape.', '7v7 (+GK) in the low half of the pitch; blues in a 4-3 shape from the 4-3-3, two small goals at the halfway end.', 'Blues build up from the GK, use any numerical advantage to break forward and score in either small goal. Reds man-mark the whole pitch to force quick decisions, win it and counter.', 'Reds score within 10-12 seconds of winning the ball.', 'Variation 2: reds press ultra-aggressively up to the GK, all blues tightly marked except the free centre back, who must be found via link players.', 'Off-ball movement to lose markers; time supporting runs; accurate passing; read pressing cues to spot the free player; link player principles.', '7 (+GK) v 7', 15, 15, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 360),
  ('GK long pass vs man marking 6v6', 'phase_of_play', 'opposed', 'in_possession', 180, 181, 'Session 9: Practice 4', 'Flick / Klopp / Emery build up patterns', 'Create and use space with a long pass from the GK to the forward or wingers against full pitch man marking.', '6v6 (+GKs); blues in a 3-3 front shape from the 4-3-3 (centre backs and full backs left out), reds defend in a 4-2; two small goals for the reds'' counter.', 'Coach passes to the blue GK, who plays long to the forward (target player) or a winger after off-ball movement; the forward holds up and lays off to a supporting midfielder, then blues attack to score.', 'GK must pass within 4-5 seconds of receiving from the coach. Reds press high, win it and score in the small goals within 10-12 seconds.', 'Variation 2: forward uses speed to beat his marker and receive in behind directly from the GK. Can be adapted to a double pivot (4-2-3-1).', NULL, '6v6 (+GKs)', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 370),
  ('Read pressing triggers 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 182, 182, 'Session 9: Practice 5', 'Flick / Klopp / Emery build up patterns', 'Adapt the build up to the type of press: find the free player vs ultra-aggressive press, or make and exploit space vs high press.', '11v11 on three quarters of a full pitch.', 'Reds use full pitch man marking with either an ultra-aggressive press up to the GK or a high press on the first receiver; blues read which it is and progress to score.', 'Reds win the ball and counter to score within 10-12 seconds.', NULL, 'Vs ultra-aggressive press find and use the free player; vs high press coordinate synchronised movements.', '11v11', 22, 22, '3/4 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 380)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'beat-the-press-with-single-double-pivots-build-up-play-and-sessions-from-flick-k') b;
